cd /tmp && node -e "
const sharp = require('sharp');
(async () => {
  await sharp('/task/screenshots/product.png').resize(700).toFile('/tmp/resized/product_sm.png');
  // Split product into top/bottom halves
  const meta = await sharp('/task/screenshots/product.png').metadata();
  console.log('orig:', meta.width, meta.height);
  // Resized to 700 wide => 700/1440 ratio
  const ratio = 700/1440;
  const newH = Math.round(meta.height * ratio);
  console.log('new h:', newH);
  // Split into 2 halves
  await sharp('/tmp/resized/product_sm.png').extract({left:0, top:0, width:700, height: Math.floor(newH/2)}).toFile('/tmp/resized/product_top.png');
  await sharp('/tmp/resized/product_sm.png').extract({left:0, top:Math.floor(newH/2), width:700, height: newH - Math.floor(newH/2)}).toFile('/tmp/resized/product_bot.png');
})();
